import { CapacitorHttp } from '@capacitor/core';
import type { HttpHeaders, HttpResponse, HttpResponseType } from '@capacitor/core';

export interface Product {
  id: number;
  name: string;
  price: number;
}

export interface OrderRequest {
  productId: number;
  quantity: number;
}

export interface OrderResponse {
  orderId: string;
  productId: number;
  quantity: number;
  total: number;
}

export interface ErrorPayload {
  error?: string;
}

/**
 * Typed error thrown by {@link ApiClient} when the underlying HTTP response
 * is not a 2xx success. Carries the HTTP status code, URL, and parsed body
 * so callers can react programmatically.
 */
export class ApiHttpError extends Error {
  public readonly status: number;
  public readonly url: string;
  public readonly body: unknown;
  public readonly headers: HttpHeaders;

  constructor(
    message: string,
    status: number,
    url: string,
    body: unknown,
    headers: HttpHeaders = {},
  ) {
    super(message);
    this.name = 'ApiHttpError';
    this.status = status;
    this.url = url;
    this.body = body;
    this.headers = headers;
    // Preserve proper prototype chain when targeting older runtimes.
    Object.setPrototypeOf(this, ApiHttpError.prototype);
  }
}

export interface ApiClientOptions {
  /** Base URL of the API, e.g. "http://localhost:8787". */
  baseUrl: string;
}

export class ApiClient {
  private readonly baseUrl: string;

  constructor(options: ApiClientOptions) {
    this.baseUrl = options.baseUrl.replace(/\/+$/, '');
  }

  async listProducts(): Promise<Product[]> {
    return this.request<Product[]>('GET', '/api/products');
  }

  async getProduct(id: number): Promise<Product> {
    return this.request<Product>('GET', `/api/products/${id}`);
  }

  async createOrder(body: OrderRequest, apiKey: string): Promise<OrderResponse> {
    return this.request<OrderResponse>('POST', '/api/orders', {
      data: body,
      headers: {
        'Content-Type': 'application/json',
        'X-Api-Key': apiKey,
      },
    });
  }

  /**
   * Low-level helper around CapacitorHttp that:
   *   - serializes JSON bodies,
   *   - propagates custom headers,
   *   - converts any non-2xx response into a typed {@link ApiHttpError}.
   */
  private async request<T>(
    method: string,
    path: string,
    init: {
      data?: unknown;
      headers?: HttpHeaders;
      responseType?: HttpResponseType;
    } = {},
  ): Promise<T> {
    const url = `${this.baseUrl}${path}`;
    const options = {
      url,
      method,
      headers: init.headers,
      data: init.data as never,
      responseType: init.responseType ?? 'json',
    };

    let response: HttpResponse;
    try {
      response = await CapacitorHttp.request(options);
    } catch (err) {
      // Network-level failure (connection refused, DNS, etc.). Surface as a
      // zero-status ApiHttpError so callers can still inspect it uniformly.
      const message = err instanceof Error ? err.message : String(err);
      throw new ApiHttpError(`Network error contacting ${url}: ${message}`, 0, url, undefined, {});
    }

    if (response.status < 200 || response.status >= 300) {
      const body = response.data as ErrorPayload | undefined;
      const message =
        (body && typeof body === 'object' && typeof body.error === 'string'
          ? body.error
          : `Request failed with status ${response.status}`);
      throw new ApiHttpError(
        message,
        response.status,
        response.url,
        response.data,
        response.headers,
      );
    }

    return response.data as T;
  }
}

import { ApiClient, ApiHttpError } from './api-client.js';

const BASE_URL = process.env.API_BASE_URL ?? 'http://localhost:8787';
const VALID_API_KEY = 'local-dev-key-123';
const INVALID_API_KEY = 'definitely-not-the-right-key';

interface ResultPayload {
  productCount: number;
  product2Name: string;
  orderId: string;
  orderTotal: number;
  missingProductStatus: number;
  unauthorizedStatus: number;
}

async function main(): Promise<void> {
  const client = new ApiClient({ baseUrl: BASE_URL });

  // 1. List all products
  const products = await client.listProducts();
  const productCount = products.length;

  // 2. Fetch the product with id 2
  const product2 = await client.getProduct(2);
  const product2Name = product2.name;

  // 3. Create an order for productId 3, quantity 2, correct API key
  const order = await client.createOrder(
    { productId: 3, quantity: 2 },
    VALID_API_KEY,
  );
  const orderId = order.orderId;
  const orderTotal = order.total;

  // 4. Attempt to fetch product id 999 -> expect 404
  let missingProductStatus = 0;
  try {
    await client.getProduct(999);
    throw new Error('Expected getProduct(999) to reject with ApiHttpError');
  } catch (err) {
    if (!(err instanceof ApiHttpError)) {
      throw err;
    }
    missingProductStatus = err.status;
  }

  // 5. Attempt to create an order with an incorrect API key -> expect 401
  let unauthorizedStatus = 0;
  try {
    await client.createOrder(
      { productId: 3, quantity: 2 },
      INVALID_API_KEY,
    );
    throw new Error('Expected createOrder with bad key to reject with ApiHttpError');
  } catch (err) {
    if (!(err instanceof ApiHttpError)) {
      throw err;
    }
    unauthorizedStatus = err.status;
  }

  const result: ResultPayload = {
    productCount,
    product2Name,
    orderId,
    orderTotal,
    missingProductStatus,
    unauthorizedStatus,
  };

  // Print exactly one line starting with "RESULT: " followed by a JSON object.
  process.stdout.write(`RESULT: ${JSON.stringify(result)}\n`);
}

main().catch((err) => {
  // Surface failure details on stderr but keep the contract that any
  // RESULT: line we emit is the final, machine-readable outcome.
  // eslint-disable-next-line no-console
  console.error('[roundtrip] failed:', err);
  process.exit(1);
});

